'use strict';
const WORLDS=[{key:'seed',name:'ピクセル',count:0},{key:'window',name:'生成アプリ',count:6,sample:9},{key:'app',name:'デザインアプリ',count:10},{key:'desktop',name:'デスクトップ',count:11,sample:13},{key:'studio',name:'作業スペース',count:14,sample:17},{key:'os',name:'環境マネージャー',count:18,sample:22},{key:'display',name:'ネットワークデスクトップ',count:23,sample:26},{key:'complete',name:'統合管理',count:27}];
let uiState={view:null,partsOpen:true,canvasOpen:true,filesOpen:false,remoteOpen:true,canvasMax:false,remoteMax:false,tool:'pointer',layer:'photo',zoom:50,activeHost:0};
function worldLevel(){let level=0;WORLDS.forEach((w,i)=>{if(state.owned.length>=w.count)level=i});return level}
function number(n){if(n<1e4)return Number.isInteger(n)?n.toLocaleString('ja-JP'):n.toFixed(n<10?1:0);if(n<1e8)return(n/1e4).toFixed(n<1e5?1:0)+'万';if(n<1e12)return(n/1e8).toFixed(1)+'億';return n.toExponential(1)}
const svgPaths={pointer:'M4 2v17l5-5 4 7 3-2-4-7 7-1Z',type:'M4 5h16M12 5v16M8 21h8',rect:'M4 4h16v16H4Z',circle:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',image:'M3 4h18v16H3ZM3 15l5-5 6 6 3-3 4 4M15 8h.1',folder:'M3 5h7l2 3h9v12H3Z',file:'M6 2h8l5 5v15H6ZM14 2v6h5M9 13h7M9 17h7',play:'M8 4l13 8L8 20Z',pause:'M7 4v16M17 4v16',save:'M4 3h14l3 3v15H3V3ZM7 3v7h10V3M7 21v-8h10v8',settings:'M9 3h6l1 4 4 1v7l-4 1-1 5H9l-1-5-4-1V8l4-1ZM15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',grid:'M3 3h7v7H3ZM14 3h7v7h-7ZM3 14h7v7H3ZM14 14h7v7h-7Z',layers:'m3 8 9-5 9 5-9 5Zm0 5 9 5 9-5M3 18l9 5 9-5',host:'M3 3h18v12H3ZM12 15v6M7 21h10',plus:'M12 4v16M4 12h16',back:'M15 5l-7 7 7 7',check:'m5 12 5 5 10-11',arrow:'M5 19 19 5M7 5h12v12',network:'M3 3h6v6H3ZM15 15h6v6h-6ZM9 6h9v9M6 9v9h9',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M12 6v7l4 2',terminal:'m5 7 5 5-5 5M13 17h7',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12ZM15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0'};
function ico(name){return `<svg class="ui-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${svgPaths[name]||svgPaths.grid}"/></svg>`}
function upgradeIcon(id){const names={border:'rect',color:'image',font:'type',shadow:'layers',motion:'play',window:'host',slider:'settings',gauge:'clock',corners:'rect',tabs:'image',break:'grid',wallpaper:'folder',dock:'grid',atelier:'grid',gradient:'layers',glass:'layers',light:'eye',blueprint:'host',palette:'image',material:'settings',constellation:'play',harmony:'layers',workspaces:'network',launchpad:'grid',network:'network',panorama:'host',ecosystem:'grid'};return ico(names[id]||'rect')}
function mark(kind,label){return `<i class="app-mark mark-${kind}" aria-hidden="true">${label}</i>`}
function head(title,kind='pixel',win=null){return `<div class="window-head" ${win?'data-drag="'+win+'"':''}>${mark(kind,kind==='canvas'?'C':kind==='files'?'▰':kind==='host'?'V':'P')}<span class="window-name">${title}</span>${win?`<div class="window-buttons"><button class="minimize" data-act="minimize" data-window="${win}" aria-label="${title}を最小化">−</button><button data-act="maximize" data-window="${win}" aria-label="${title}を最大化">□</button><button class="close" data-act="minimize" data-window="${win}" aria-label="${title}を閉じる">×</button></div>`:`<div class="window-buttons"><button data-act="settings" aria-label="設定">${ico('settings')}</button></div>`}</div>`}
function menu(){return '<div class="window-menu"><button data-act="files">ファイル</button><button data-act="design">編集</button><button data-act="toggle-parts">部品</button><button data-act="history">履歴</button><button data-act="settings">設定</button></div>'}
function resource(){return `<div class="resource-line"><span>ピクセル</span><b data-value="balance">${number(state.px)}</b></div>`}
function componentBox(compact=false){const r=nextRecipe();return `<div class="component-box">${compact?"":resource()}${r?`<div class="component-icon" aria-hidden="true">${upgradeIcon(r.id)}</div><h3>${r.name}</h3><p>${r.desc}</p><div class="component-effect">${r.effect}</div><button class="primary-button" data-act="purchase" data-purchase><span>作成する</span><span>${number(r.cost)} px</span></button><div class="purchase-progress"><i data-price-progress></i></div><div class="price-wait" data-price-wait></div>`:'<div class="component-finished">すべての環境を構築しました。<br><button class="text-button" data-act="history">作成の履歴を見る</button></div>'}</div>`}
function cursorBox(){if(!has('border'))return '';return `<div class="cursor-box"><div class="cursor-caption"><span>↖　カーソル</span><span data-value="cursor">${state.cursors} 個</span></div><button class="soft-button" data-act="cursor" data-cursor-buy>${number(cursorCost())} px で追加</button></div>`}
function statusBar(extra=''){return `<div class="status-strip"><span><i class="online-dot"></i>自動生成 <span data-value="rate">${number(rate())} px / 秒</span></span>${extra}<span class="status-end" data-save>自動保存</span></div>`}
function livePreview(level,options={}){return `<div class="preview-frame" data-level="${level}" inert aria-hidden="true">${screen(level,{...options,mini:true})}</div>`}
function seedScreen(){const r=nextRecipe();return `<div class="seed-center">${state.total>0?`<div class="seed-count"><span data-value="balance">${number(state.px)}</span> px</div>`:''}<button class="seed-generate" data-act="generate">${has('border')?'ピクセルを生成する':'ピクセルを1つ生成する'}</button></div>${state.total>0?`<div class="seed-recipes"><div class="seed-recipe-row"><button data-act="purchase" data-purchase>${r.name}を作る</button><span>${number(r.cost)} px</span></div>${has('border')?`<div class="seed-recipe-row"><button data-act="cursor" data-cursor-buy>カーソルを追加</button><span>${number(cursorCost())} px</span></div>`:''}<p data-price-wait></p></div><button class="seed-options" data-act="settings">設定</button>`:''}${state.cursors?'<i class="seed-cursor"></i>':''}`}
function generator(){return `<section class="window generator-full">${head('ピクセルジェネレーター','pixel')}${menu()}<div class="generator-body"><div class="generator-work"><div class="generator-card"><div class="card-label">生成ジョブ / pixel_001</div><div class="generator-number"><span data-value="balance">${number(state.px)}</span><small>px</small></div><div class="generator-controls"><button class="primary-button" data-act="generate">${ico('play')}生成する</button></div><div class="engine-line"><span>自動生成</span><span data-value="rate">${number(rate())} px / 秒</span></div>${has('gauge')?'<div class="engine-gauge"><i data-gauge></i></div><div class="engine-line"><span>蓄積ゲージ</span><span data-value="gauge">40%</span></div>':''}${has('slider')?`<div class="rhythm-line"><span>生成リズム</span><button class="soft-button" data-act="rhythm">${['手動優先','バランス','自動優先'][state.rhythm]}</button></div>`:''}</div><div class="engine-help">生成したピクセルは、右の部品一覧から新しい画面の材料として使えます。</div></div><aside class="generator-side"><div class="side-heading">部品を作成</div>${componentBox()}${cursorBox()}</aside></div>${statusBar()}</section>`}
function canvasApp({desktop=false,mini=false}={}){const art=state.design%2;return `<section class="window ${desktop?'desktop-app '+(uiState.canvasOpen?'':'minimized')+' '+(uiState.canvasMax?'maximized':''):'canvas-full'}" data-window-id="canvas">${head('Canvas — 海岸の記録.canvas','canvas',desktop?'canvas':null)}${menu()}<div class="canvas-toolbar"><button class="toolbar-button ${uiState.tool==='pointer'?'selected':''}" data-act="tool" data-tool="pointer">${ico('pointer')}選択</button><span class="toolbar-separator"></span><span class="font-picker">游ゴシック　⌄</span><span class="font-picker">32 px</span><button class="toolbar-button" data-act="design">${ico('image')}写真を変更</button><div class="toolbar-end"><button class="toolbar-button" data-act="zoom">${uiState.zoom}%</button><button class="primary-button" data-act="generate">${ico('play')}描画</button></div></div><div class="canvas-main"><div class="canvas-tools">${['pointer','type','rect','circle','image','layers'].map(t=>`<button class="${uiState.tool===t?'selected':''}" data-act="tool" data-tool="${t}" aria-label="${{pointer:'選択',type:'文字',rect:'四角形',circle:'円',image:'写真',layers:'レイヤー'}[t]}">${ico(t)}</button>`).join('')}</div><div class="document-area"><div class="ruler-horizontal"><span>0</span><span>100</span><span>200</span><span>300</span><span>400</span><span>500</span></div><div class="ruler-vertical"></div><article class="artboard ${art?'alt':''}" style="${uiState.zoom===75?'transform:scale(1.5)':''}" aria-label="海岸の記録 ポスター"><div class="artboard-photo"></div>${uiState.layer==='photo'?'<div class="photo-selection"></div>':''}<div class="artboard-copy"><div class="edition">写真記録　／　第01集</div><h1>${art?'街の記録':'海岸の記録'}</h1><div class="caption"><span>風景の記録</span><span>2026 — 01</span></div></div></article></div><aside class="canvas-inspector"><div class="inspector-tabs"><button class="active" data-act="toggle-parts">部品を作成</button><button data-act="show-layers">レイヤー</button></div>${componentBox()}${cursorBox()}<div class="inspector-section"><h3>レイヤー</h3><button class="layer-row ${uiState.layer==='photo'?'active':''}" data-act="layer" data-layer="photo"><i class="layer-thumb photo"></i>写真 / coastline.png</button><button class="layer-row ${uiState.layer==='title'?'active':''}" data-act="layer" data-layer="title"><i class="layer-thumb">T</i>タイトル</button><div class="origin-document">${livePreview(1)}<small>生成元 / pixel_001</small></div></div></aside></div>${statusBar('<span>ポスター　210 × 297 mm</span>')}</section>`}
function partsWindow(){return `<section class="window parts-window ${uiState.partsOpen?'':'minimized'}" data-window-id="parts">${head('部品ライブラリ','system','parts')}<div class="window-body">${componentBox()}${cursorBox()}</div>${statusBar()}</section>`}
function filesWindow(){return `<section class="window files-window" data-window-id="files">${head('ファイル — 制作フォルダー','files','files')}<div class="file-manager"><aside class="file-sidebar">最近のファイル<br>制作フォルダー<br>画像<br>設計図<br>設定</aside><div class="file-main"><div class="file-path">ホーム　›　制作フォルダー</div><table class="file-table"><thead><tr><th>名前</th><th>種類</th><th class="size">サイズ</th></tr></thead><tbody><tr><td><button data-act="note">制作ノート.txt</button></td><td>テキスト文書</td><td class="size">${new TextEncoder().encode(state.notes||'').length} B</td></tr><tr><td><button data-act="open-canvas">海岸の記録.canvas</button></td><td>Canvas ドキュメント</td><td class="size">編集可能</td></tr><tr><td><button data-act="photo">coastline.png</button></td><td>PNG 画像</td><td class="size">2.55 MB</td></tr><tr><td><button data-act="settings">環境の設定</button></td><td>システム設定</td><td class="size">—</td></tr></tbody></table></div></div><div class="status-strip">4 個の項目<span class="status-end">制作フォルダー</span></div></section>`}
function desktopIcons(network=false){return `<nav class="desktop-shortcuts" aria-label="デスクトップのファイル"><button class="desktop-shortcut" data-act="${network?'open-remote':'open-canvas'}">${mark(network?'host':'canvas',network?'V':'C')}<span>${network?'環境マネージャー':'Canvas'}</span></button><button class="desktop-shortcut" data-act="files">${mark('files','▰')}<span>制作フォルダー</span></button><button class="desktop-shortcut" data-act="note"><i class="file-paper"></i><span>制作ノート.txt</span></button><button class="desktop-shortcut" data-act="toggle-parts">${mark('system','＋')}<span>部品ライブラリ</span></button></nav>`}
function taskbar(level=3){const network=level>=6;return `<nav class="taskbar" aria-label="タスクバー"><button class="start-button" data-act="settings" aria-label="システム設定"><span class="start-logo"><i></i><i></i><i></i><i></i></span></button><button class="task-button ${(network?uiState.remoteOpen:uiState.canvasOpen)?'active':''}" data-act="${network?'open-remote':'open-canvas'}">${mark(network?'host':'canvas',network?'V':'C')}<span>${network?'環境マネージャー':'Canvas'}</span></button><button class="task-button" data-act="files" aria-label="ファイルを開く">${mark('files','▰')}</button><button class="task-button ${uiState.partsOpen?'active':''}" data-act="toggle-parts">${mark('system','＋')}<span>部品</span></button><button class="task-button" data-act="spaces" aria-label="作業スペースを表示">${ico('grid')}</button><div class="task-spacer"></div><span class="tray-balance"><span data-value="balance">${number(state.px)}</span> px</span><button class="tray-button" data-act="generate" aria-label="ピクセルを生成">＋</button><button class="tray-button" data-act="settings" aria-label="設定">${ico('settings')}</button><div class="tray-clock"><span data-clock></span><small data-date></small></div></nav>`}
function desktop(network=false,options={}){return `${desktopIcons(network)}${network?`<section class="window desktop-app remote-window ${uiState.remoteOpen?'':'minimized'} ${uiState.remoteMax?'maximized':''}" data-window-id="remote">${head('Remote — LOCAL-01 / 環境マネージャー','host','remote')}<div class="remote-body" data-act="enter-manager">${livePreview(5,{...options})}</div><div class="status-strip"><span><i class="online-dot"></i>接続中</span><span>ローカル環境 / メインセッション</span><button class="text-button" data-act="enter-manager">操作する ↗</button><span class="status-end">1280 × 800</span></div></section>`:canvasApp({desktop:true})}${partsWindow()}${uiState.filesOpen?filesWindow():''}<div class="desktop-note">${ico(network?'network':'check')}<div class="note-copy">${network?'LOCAL-01 / バックグラウンド生成':'海岸の記録.canvas'}<small>${network?'接続中の環境で生成を継続':'制作フォルダーに保存済み'}</small></div></div>${taskbar(network?6:3)}`}
function activity(limit=3,logs=false){const entries=state.history.slice(-limit).reverse();if(!entries.length)return logs?'<div class="log-line"><time>--:--:--</time><span class="log-status">READY</span><span>生成エンジンを待機しています</span></div>':'<div class="activity-line"><span>作成の履歴はここに表示されます。</span></div>';return entries.map(h=>{const r=RECIPES.find(r=>r.id===h.id);if(!r)return '';const t=new Intl.DateTimeFormat('ja-JP',{hour:'2-digit',minute:'2-digit',second:logs?'2-digit':undefined,hour12:false,timeZone:'Asia/Tokyo'}).format(new Date(h.at));return logs?`<div class="log-line"><time>${t}</time><span class="log-status">CREATED</span><span>${r.name}</span></div>`:`<div class="activity-line"><time>${t}</time><b>${r.name}</b><span>作成完了</span></div>`}).join('')}
function spaces(){return `<header class="spaces-top">${ico('grid')}<h1>作業スペース</h1><div class="top-actions"><span class="top-balance"><span data-value="balance">${number(state.px)}</span> px</span><button class="dark-soft" data-act="generate">＋ 生成</button><button class="dark-soft" data-act="toggle-parts">部品を作る</button></div></header><div class="spaces-layout"><section class="workspace-card selected"><div class="workspace-caption"><strong>制作</strong><button data-act="enter-desktop">このスペースを開く ↗</button></div>${livePreview(3)}<div class="workspace-activity"><h3>最近の作成</h3>${activity(3)}</div><div class="workspace-footer"><p><span data-value="rate">${number(rate())} px / 秒</span><br>選択したスペースで生産を継続中</p><button class="primary-button" data-act="toggle-parts">＋ 部品を追加</button></div></section><div class="workspace-aside"><section class="workspace-card"><div class="workspace-caption"><strong>資料</strong><button data-act="photo">画像を見る</button></div>${livePreview(3,{night:true})}</section><section class="workspace-card"><div class="workspace-caption"><strong>自動処理</strong><button data-act="engine">生成元を開く</button></div>${livePreview(1)}</section></div></div>${uiState.partsOpen?partsWindow():''}${taskbar(4)}`}
function systems(){return `<section class="systems-app">${head('Environment Manager — ローカル環境','host')}<div class="systems-toolbar"><button class="dark-soft main-action" data-act="purchase" data-purchase>${ico('plus')}新しい環境</button><button class="dark-soft" data-act="generate">${ico('play')}生成</button><button class="dark-soft" data-act="auto-toggle">${ico('settings')}自動購入</button><div class="toolbar-end"><i class="online-dot"></i><span>ローカルホスト</span><span data-clock></span></div></div><div class="systems-layout"><nav class="systems-nav"><h3>ローカル環境</h3>${['メイン環境','資料用スペース','自動処理'].map((n,i)=>`<button class="host-item ${uiState.activeHost===i?'selected':''}" data-act="host" data-host="${i}">${ico(i===2?'terminal':'host')}<span>${n}<small>LOCAL-0${i+1} ・ 実行中</small></span></button>`).join('')}<div class="nav-bottom">作成した環境はすべて<br>このブラウザ内で動作します。</div></nav><section class="systems-center"><div class="environment-heading"><h2>${['メイン環境','資料用スペース','自動処理'][uiState.activeHost]}</h2><button class="dark-soft" data-act="connect-host">環境を開く ↗</button><span class="environment-status"><i class="online-dot"></i>実行中</span></div>${livePreview(uiState.activeHost===2?1:uiState.activeHost===1?3:4,{night:uiState.activeHost===1})}<div class="session-tabs"><b>イベント</b><span>作成履歴</span><span>生成エンジン</span></div><div class="systems-log">${activity(7,true)}</div></section><aside class="systems-inspector"><div class="inspector-label">環境の情報</div><div class="system-properties"><div><span>ホスト名</span><b>LOCAL-0${uiState.activeHost+1}</b></div><div><span>状態</span><b>実行中</b></div><div><span>カーソル</span><b data-value="cursor">${state.cursors} 個</b></div><div><span>自動生成</span><b data-value="rate">${number(rate())} px / 秒</b></div></div>${componentBox()}${cursorBox()}</aside></div>${statusBar('<span>LOCAL-01 / メイン環境</span>')}</section>`}
function control(){return `<header class="control-top">${mark('host','N')}<h1>環境の統合管理</h1><small>ローカルネットワーク</small><div class="top-actions"><span class="top-balance"><span data-clock></span></span><button class="dark-soft" data-act="generate">＋ 生成</button><button class="dark-soft" data-act="settings">${ico('settings')}設定</button></div></header><div class="control-main"><nav class="control-rail" aria-label="管理機能"><button class="active" data-act="history" aria-label="作成履歴">${ico('grid')}</button><button data-act="manager" aria-label="環境マネージャーを開く">${ico('host')}</button><button data-act="files" aria-label="ファイルを開く">${ico('folder')}</button><button data-act="settings" aria-label="設定">${ico('settings')}</button></nav><div class="control-scenes"><section class="control-session primary-session"><div class="control-session-head"><strong>LOCAL-01 / メイン</strong><span><i class="online-dot"></i>接続中</span></div>${livePreview(6)}<div class="session-tools"><button class="dark-soft" data-act="enter-network">セッションを開く ↗</button><button class="dark-soft" data-act="manager">環境を管理</button></div><div class="session-note"><h3>最近の変更</h3>${activity(4)}</div></section><section class="control-session"><div class="control-session-head"><strong>LOCAL-02 / 資料</strong><span>実行中</span></div>${livePreview(3)}</section><section class="control-session"><div class="control-session-head"><strong>LOCAL-03 / 自動処理</strong><span>実行中</span></div>${livePreview(1)}</section></div><aside class="control-summary"><h2>すべての環境</h2><div class="control-total"><span data-value="balance">${number(state.px)}</span> <small>px</small></div><div class="control-rate" data-value="rate">${number(rate())} px / 秒</div>${componentBox(true)}${cursorBox()}</aside></div><footer class="control-bottom"><span><i class="online-dot"></i>ローカル接続</span><span>3 環境を表示</span><span class="status-end" data-save>自動保存</span></footer>${uiState.filesOpen?filesWindow():''}${uiState.managerOpen?`<section class="window manager-popover" data-window-id="manager">${head('環境マネージャー','host','manager')}${systems()}</section>`:''}`}
function screen(level,options={}){const kind=['seed','generator','canvas','desktop','spaces','systems','desktop night network-desktop','control'][level];let content=level===0?seedScreen():level===1?generator():level===2?canvasApp():level===3?desktop(false,options):level===4?spaces():level===5?systems():level===6?desktop(true,options):control();return `<div class="screen screen-${kind} ${options.night&&level===3?'night':''} ${options.mini?'is-preview':''}" data-world="${level}">${content}${!options.mini&&options.showControls?'<div class="preview-hint"><button data-act="preview-controls">表示</button></div>':''}${!options.mini&&uiState.view!==null?'<button class="return-session" data-act="return">全体へ戻る ↗</button>':''}</div>`}





